    {
      "wcagCode": "G146",
      "violationName": "Missing Alternate Text for Images",
      "category": "semantic",
      "html": "<span class=\"link\" onclick=\"location.href='https://act-rules.github.io/'\" role=\"lnik\">ACT rules</span>",
      "target": null,
      "description": "The span element with the class 'link' is used to represent a link, but it does not have an alt attribute which is required for accessibility. This can cause issues for users who rely on screen readers or other assistive technologies.",
      "impact": "serious",
      "confidence": 1.0
    }
  ]
}

