{
  "rule_id": "iframe-no-focusable-content",
  "title": "Iframe with Focusable Content",
  "description": "This rule ensures that any non-focusable <code>iframe</code> element containing focusable content does not allow the user to navigate into its nested browsing context using standard keyboard navigation.",
  "applicability": {
    "rule_applies_to": [
      "non-focusable iframe elements with focusable content"
    ]
  },
  "expectation": {
    "nested_browsing_context_contains_visible_elements_in_focus_navigation": false,
    "definition_of_nested_browsing_context": "A nested browsing context is defined as an <code>iframe</code> element whose owner document is the container document of another browsing context.",
    "definition_of_visible_elements": "Elements are considered visible if they have a positive <code>tabindex</code> attribute value or are part of the sequential focus navigation."
  },
  "assumptions": {
    "interactive_content_provides_functionality": true,
    "keyboard_navigation_supports_functionality": false
  },
  "accessibility_support": {
    "major_accessibility_issues": false,
    "known_accessibility_issues": []
  },
  "background": {
    "tabindex_attribute_value_of_iframe_elements": "-1",
    "effect_of_tabindex_attribute_on_focus_navigation": "Prevents focus from being moved into the browsing context of an <code>iframe</code> element, even though its content is still included in the sequential focus navigation."
  },
  "bibliography": [
    {
      "url": "https://www.w3.org/WAI/WCAG21/Understanding/keyboard",
      "title": "Understanding Success Criterion 2.1.1: Keyboard"
    },
    {
      "url": "https://www.w3.org/WAI/WCAG21/Techniques/general/G202",
      "title": "WCAG Technique G202: Ensuring keyboard control for all functionality"
    }
  ],
  "test_cases": [
    {
      "passed": true,
      "description": "The <code>iframe</code> element has a negative <code>tabindex</code> attribute value, preventing focus from being moved into its browsing context."
    },
    {
      "passed": false,
      "description": "The <code>iframe</code> element does not have a negative <code>tabindex</code> attribute value and contains visible elements in the sequential focus navigation."
    }
  ]
}

